import json, pprint
t = json.load(open('/tmp/claude-1000/-workspaces-fhir-agent/ece4ab01-8424-4908-a0ba-5c09fa9936d4/scratchpad/knowledge_tables.json'))
lic = open('/tmp/claude-1000/-workspaces-fhir-agent/ece4ab01-8424-4908-a0ba-5c09fa9936d4/scratchpad/cmb/x/comorbidipy-0.5.0.dist-info/LICENSE').read().strip()
def lit(o): return pprint.pformat(o, width=100, sort_dicts=True)
src = f'''"""Published clinical knowledge as data: the Hospital Frailty Risk Score and the Charlson and
Elixhauser comorbidity mappings (ICD-10, Quan variants), with their standard weights.

Vendored verbatim from comorbidipy 0.5.0 (https://pypi.org/project/comorbidipy/, MIT licence,
reproduced below) — the library itself is not a dependency: it no longer imports under pandas 3.
Sources: Gilbert et al., Lancet 2018 (HFRS: 109 three-character ICD-10 codes with points);
Quan et al., Med Care 2005 (Charlson/Elixhauser ICD-10 coding algorithms); Charlson and
van Walraven weightings as packaged by comorbidipy.

MEPS releases only THREE-character ICD-10 codes. HFRS is defined at exactly that level. Charlson
and Elixhauser mix 3- and 4-character codes, so at 3 characters they are APPROXIMATE (see
`meps_categories`): a 3-character code counts toward a category if the category lists that code,
or any 4-character code beginning with it — over-inclusive by design, and labelled as such.

--- comorbidipy licence ---
{lic}
"""
from __future__ import annotations

HFRS_POINTS: dict[str, float] = {lit(t["hfrs"])}

CHARLSON_ICD10_QUAN: dict[str, list[str]] = {lit(t["charlson_icd10_quan"])}

ELIXHAUSER_ICD10_QUAN: dict[str, list[str]] = {lit(t["elixhauser_icd10_quan"])}

CHARLSON_WEIGHTS: dict[str, float] = {lit(t["charlson_weights"]["charlson"])}

ELIXHAUSER_WEIGHTS_VW: dict[str, float] = {lit(t["elixhauser_weights"]["vw"])}


def meps_categories(mapping: dict[str, list[str]]) -> dict[str, set[str]]:
    """Category -> the set of THREE-character codes that (approximately) indicate it."""
    return {{cat: {{c[:3] for c in codes}} for cat, codes in mapping.items()}}


def scores(icd3_codes: set[str]) -> dict[str, float]:
    """Knowledge-based features for one person's set of 3-character ICD-10 codes."""
    charlson = meps_categories(CHARLSON_ICD10_QUAN)
    elix = meps_categories(ELIXHAUSER_ICD10_QUAN)
    ch = {{c for c, codes in charlson.items() if icd3_codes & codes}}
    el = {{c for c, codes in elix.items() if icd3_codes & codes}}
    return {{
        "hfrs": float(sum(HFRS_POINTS.get(c, 0.0) for c in icd3_codes)),
        "charlson_approx": float(sum(CHARLSON_WEIGHTS.get(c, 0) for c in ch)),
        "elixhauser_vw_approx": float(sum(ELIXHAUSER_WEIGHTS_VW.get(c, 0) for c in el)),
        "elixhauser_count_approx": float(len(el)),
    }}
'''
open('outcome-prediction-lab/src/outcome_prediction_lab/knowledge.py','w').write(src)
